import {Engine} from './js/engine.js';import {makeWorld} from './js/worlds.js';import {Caretaker} from './js/caretaker.js';
const e=new Engine(document.querySelector('canvas'),128,128),b=new Float32Array(65536),a=new Float32Array(65536),out=[];
const defaults={dt:.1,speed:1,radius:13,massConserve:false,genome:true,metabolism:true,eat:true,predPayoff:.35,mu:.15,sigma:.017,mut:.003,light:.35,time:0,curiosity:0,massScale:1,poke:[-1,-1],pokeR:.045,pokeAmt:.9,pokeErase:false};
function measure(t){e.readback(b);e.readback(a,'s1');let mass=0,peak=0,energy=0;for(let i=0;i<b.length;i+=4){for(let k=0;k<4;k++)if(!Number.isFinite(b[i+k])||!Number.isFinite(a[i+k]))throw Error('Nonfinite');mass+=b[i];peak=Math.max(peak,b[i]);energy+=b[i+1];}if(e.gl.getError())throw Error('GPU error');return{t,mass,peak,energy};}
const cases=[['baseline-10000',{genome:false,mut:0}],['corrected-zero-mutation',{mut:0}],['baseline-dark',{genome:false,mut:0,light:0}],['baseline-full-light',{genome:false,mut:0,light:1}]];
document.querySelector('#start').onclick=async()=>{document.querySelector('#start').disabled=true;try{for(const[name,patch,care]of cases){const p={...defaults,...patch},agent=new Caretaker();let rs=12345;const rand=()=>((rs=(Math.imul(rs,1664525)+1013904223)>>>0)/4294967296);e.seed(makeWorld('glider',128,128,{radius:13,seed:260924}));const samples=[measure(0)],actions=[];for(let t=1;t<=10000;t++){p.time+=p.dt;e.step(p);if(t%30===0){const m=measure(t);samples.push(m);if(care&&t%180===0){const act=agent.observe({mass:m.mass,ratio:m.mass/samples[0].mass,energyPerMass:m.energy/Math.max(m.mass,1)},rand);Object.assign(p,{light:act.light,mut:act.mut});actions.push({t,...act});}e.render(0,{x:0,y:0,zoom:1},{aspect:1});document.querySelector('#status').textContent=name+' step '+t+' mass '+m.mass.toFixed(2);await new Promise(r=>setTimeout(r,0));if(m.peak<.04)break;}}out.push({name,params:{...defaults,...patch},samples,actions});const blob=new Blob([JSON.stringify(out)],{type:'application/json'});const link=document.querySelector('#download');if(link.href.startsWith('blob:'))URL.revokeObjectURL(link.href);link.href=URL.createObjectURL(blob);link.hidden=false;document.querySelector('#log').textContent=out.map(x=>x.name+': '+JSON.stringify(x.samples.at(-1))).join('\n');}document.querySelector('#status').textContent='COMPLETE';}catch(err){document.querySelector('#status').textContent='ERROR '+err.message;}};
